import numpy as np

def get_Ri(i):
    if i == 0: return np.array([1, 0, 0])
    if i == 1: return np.array([0, 1, 0])
    if i == 2: return np.array([0, 0, 1])

    R = {}
    R[0] = np.array([1, 0, 0])
    R[1] = np.array([0, 1, 0])
    R[2] = np.array([0, 0, 1])

    for n in range(3, i + 1):
        # r^n = 10*r^(n-3) - r^(n-1) - r^(n-2)
        # Let R_n = (a_n, b_n, c_n)
        # R_n = 10*R_{n-3} - R_{n-1} - R_{n-2} (in vector notation, coefficients are scaled)

        a_n = 10 * R[n-3][0] - R[n-1][0] - R[n-2][0]
        b_n = 10 * R[n-3][1] - R[n-1][1] - R[n-2][1]
        c_n = 10 * R[n-3][2] - R[n-1][2] - R[n-2][2]
        R[n] = np.array([a_n, b_n, c_n])
    return R[i]

# Calculate Ri up to i=15
R_values = {i: get_Ri(i) for i in range(16)}

print("i | a_i | b_i | c_i")
for i in range(16):
    a, b, c = R_values[i]
    print(f"{i:2} | {a:3} | {b:3} | {c:3}")

